public int minOperations(int[] arr) {
    long running = 0;
    int ops = 0;
    for (int v : arr) {
        running += v;
        if (running < 0) {
            ops++;
            running = 0;
        }
    }
    return ops;
}

public long totalCost(int[] servers, int m) {
    TreeMap<Integer, Integer> ms = new TreeMap<>();
    for (int s : servers) ms.merge(s, 1, Integer::sum);

    long total = 0;
    for (int c = 0; c < m; c++) {
        int hi = ms.lastKey();
        int lo = ms.firstKey();
        total += (long) hi + lo;

        if (ms.merge(hi, -1, Integer::sum) == 0) ms.remove(hi);
        ms.merge(hi - 1, 1, Integer::sum);
    }
    return total;
}
